    // --- Gemini Flavor Texts ---
    "チャイムが鳴り響く...": "チャイムが なりひびく...",
    "廊下の奥から視線を感じる...": "ろうかの おくから だれかが みている...",
    "給食のいい匂いがする。": "きゅうしょくの いい においが する。",
    "遠くでボールの音がした。": "とおくで ボールの おとが した。",
    "この教室は何かがおかしい...": "この きょうしつは なにかが おかしい...",
    "背筋に悪寒が走る。": "ぞわぞわ する...",
    "静寂が逆に恐ろしい...": "しずかすぎて こわい...",
    "黒板に不気味な文字が書かれている。": "こくばんに ブキミな もじが かいてある。",
    "忘れ物が落ちている...": "わすれものが おちている...",
    "殺気が満ちている！": "こわい けはいが する！",
    "水道の蛇口から水が漏れている。": "すいどうから みずが もれている。",
    "チョークの粉が舞っている。": "チョークの こなが まっている。",
    "カーテンが揺れている。": "カーテンが ゆれている。",
    "ここには誰もいないはずだ。": "ここには だれも いないはずだ。",
    "上履きが片方ない...": "うわばきが かたほう ない...",
    "窓の外に人影が見えた気がした。": "まどの そとに だれか いた きがした。",
    "理科室の人体模型と目が合った。": "じんたいもけい と めが あった。",
    "誰もいない音楽室からピアノが聞こえる。": "だれも いないのに ピアノが きこえる。",
    "下駄箱に謎の手紙が入っている。": "げたばこに なぞの てがみが ある。",
    "放送室のランプが不気味に点滅している。": "ほうそうしつの ライトが ピカピカ している。",
    "トイレのスリッパが揃えられている。": "トイレの スリッパが ならんでいる。",
    "図書室の本が勝手にめくれている。": "ほんが かってに めくれている。",
    "掲示板のポスターが剥がれかけている。": "ポスターが はがれそうだ。",
    "階段の踊り場に誰か立っている。": "かいだんに だれか たっている。",
    "体育館の暗闇からドリブルの音がする。": "たいいくかん から ボールの おとが する。",
    "家庭科室の包丁が光っている。": "ほうちょうが ぴかっと ひかった。",
    "屋上の扉がガタガタと鳴っている。": "おくじょうの ドアが ガタガタ いっている。",
    "プールの水面に何かが映っている。": "プールに なにか うつっている。",
    "用務員室から不気味な笑い声がする。": "わらいごえが きこえてくる...",
    "職員室の椅子が勝手に回っている。": "いすが かってに まわっている。",
    "算数セットの中身がバラバラだ...": "さんすうセットが バラバラだ...",
    "連絡帳に知らない予定が書かれている。": "れんらくちょうに しらない ことが かいてある。",
    "ランドセルの底にカビたパンがあった...": "ランドセルに カビたパンが あった...",
    "廊下のワックスが効きすぎている。": "ろうかが ツルツル すべる。",
    "雨漏りの音が心臓の鼓動のように聞こえる。": "あまもりの おとが ドクドク きこえる。",
    "古い木造校舎がミシミシと鳴く。": "こうしゃが ミシミシ いっている。",

    // --- Story Titles & Contents ---
    "異変の兆し": "いへんの きざし",
    "機械仕掛けの理想": "きかいじかけの りそう",
    "最後の授業": "さいごの じゅぎょう",
    "止まった時計": "とまった とけい",
    "閉じられた明日": "とじられた あした",
    "卒業なき学校": "そつぎょうなき がっこう",
    "積もる怨念": "つもる おんねん",
    "宿題の化身": "しゅくだいの けしん",
    "絶望の帳面": "ぜつぼうの ちょうめん",
