    // --- Character Selection Labels & Descriptions ---
    "固有ギミック": "とくべつな ちから",
    "初期装備": "さいしょの どうぐ",
    "【攻撃タイプ】強力な物理攻撃と自己回復で戦うバランス型。初心者におすすめ。": "【こうげき タイプ】つよい こうげきと じぶんの かいふくで たたかう。はじめての ひとに おすすめ。",
    "【捕獲タイプ】「捕獲網」で倒した敵をカードとして仲間にできる。動物たちの力を借りて戦う。": "【ほかく タイプ】「ほかくあみ」で たおした てきを カードに して なかまに できる。どうぶつの ちからで たたかう。",
    "【テクニカル】毒による継続ダメージが得意。わんぱく小学生が最初からパートナーとして参戦する。": "【テクニカル】どくの ダメージが とくい。わんぱく しょうがくせいが ずっと いっしょに たたかって くれるよ。",
    "【実験タイプ】3枚のカードを合成して超強力な「キメラカード」を作成できる。低コストスキルの連打も得意。": "【じっけん タイプ】3まいの カードを まぜて、すごく つよい カードを つくれる。スキルを たくさん つかうのも とくい。",
    "【スピード】カードを捨てることで効果を発揮する。ドッジボールでの先制攻撃が可能。": "【スピード】カードを すてると つよくなる。ドッジボールで さいしょに こうげき できるよ。",
    "【デバフ・反射】敵を弱体化させ、タイミングよく答える「応答（パリィ）」で攻撃を跳ね返す。": "【よわらせ・はんしゃ】てきを よわらせて、タイミングよく ボタンを おすと こうげきを はねかえせるよ。",
    "【戦略・保留】カードを手札に残す「保留」が得意。「物語」の力で戦局をコントロールする。": "【せんりゃく・のこす】てふだを つぎの ターンまで のこせるよ。「ものがたり」の ちからで たたかおう。",
    "【パワー】筋力を高めて一撃で粉砕する。開始時に「これまでに解放したカード」から献立を自由に組める。": "【パワー】ちからを ためて、すごい いちげきを だす！ さいしょの カードを じぶんで えらべるよ。",
    "【育成タイプ】専用の「種」を菜園で育て、超強力な植物へと成長させて戦う大器晩成型。": "【そだてる タイプ】「たね」を うえて、つよい しょくぶつに そだてて たたかう。さいごに すごく つよくなるよ。",

    "戦闘後の体力回復による高い生存能力。": "バトルが おわると HPが かいふくするから、たおれにくいよ。",
    "倒した敵を仲間の攻撃カードとして「捕獲」。": "たおした てきを ゲットして、カードとして つかえるよ。",
    "毒による固定ダメージ. 初期相棒との共闘。": "どくで ダメージを あたえる。さいしょから なかまと いっしょだよ。",
    "理科室での「3枚合成」。3つの効果を併せ持つ最強のキメラ作成可能。": "りかしつで カードを 3まい まぜて、さいきょうの カードを つくれるよ。",
    "ドロー＆ディスカード. ミニゲームでの敵撃破。": "カードをひいたり すてたり して、ドッジボールで てきを たおそう。",
    "デバフ管理と、敵の攻撃を反射する「応答」。": "てきを よわらせて、こうげきを はねかえすのが とくいだよ。",
    "手札の「保留」と、強力な物語カードの活用。": "カードを のこしたり、すごい「ものがたり」を つかって たたかおう。",
    "献立（初期デッキ）の自由にカスタマイズ。": "さいしょの カードを じゆうに きめられるよ。",
    "菜園での種まきと強力な植物カードへの進化。": "たねを うえて、つよい しょくぶつに そだてて たたかおう。",

