    "新しい学校、知らないクラスメート...。\n不安な気持ちで校庭の隅に立っていると、赤い帽子の少年が走ってきた。\n\n「よう！ お前、転校生だろ？\n俺と組んで『伝説の小学生』を目指さないか？」\n\n強引だが、悪い気はしない。彼の目は冒険への期待で輝いている。": "あたらしい がっこう、しらない クラスメート...。\nふあんな きもちで こうていの すみに 立っていると、あかい ぼうしの おとこのこが はしってきた。\n\n「よう！ おまえ、てんこうせい だろ？\nおれと くんで 『でんせつの しょうがくせい』を めざさないか？」\n\nごういん だけど、わるいきは しない。かれの めは ぼうけんに ワクワク している。",
