    "このゲームは、学習の力とデッキ構築で放課後の学校（ダンジョン）を攻略するローグライクRPGです。": "このゲームは、がくしゅうの ちからと カードで ほうかごの がっこう（ダンジョン）を こうりゃくする ゲームです。",
    "放課後の学校（ダンジョン）": "ほうかごの がっこう（ダンジョン）",
    "ユニークなカードやレリック（宝物）を集め、最強のデッキを作り上げましょう。": "いろんな カードや おたからを あつめて、さいきょうの デッキを つくりましょう。",
    "最深部（Act 4）に潜む校長先生を説得（撃破）することが最終目標です。": "さいしんぶ（Act 4）にいる こうちょうせんせいを せっとくするのが もくひょう です。",
    "校長先生": "こうちょうせんせい",
    "説得（撃破）": "せっとく（げきは）",
    "戦闘と問題": "バトルと もんだい",
    "エナジー": "エナジー",
    "カードを使うためのコスト。毎ターン回復します。": "カードを つかう パワー. まいターン かいふくする。",
    "敵の攻撃を防ぐ盾。ターン終了時に消えます。": "てきの こうげきを ふせぐ たて. ターンの おわりに きえます。",
    "敵の意図": "てきの こうどう",
    "敵の頭上のアイコンを見て、攻撃を防ぐか攻めるか判断しましょう。": "てきの あたまのうえの マークをみて、まもるか せめるか かんがえよう。",
    "問題ボーナス": "もんだい ボーナス",
    "戦闘に勝利すると学習チャレンジが発生！": "バトルに かつと がくしゅうチャレンジが はじまるよ！",
    "算数チャレンジ": "さんすう チャレンジ",
    "問題を正解するとボーナスゴールドを獲得でき、冒険が有利になります。": "もんだいに せいかいすると おかねが もらえるよ。",
    "特別教室（休憩マス）": "とくべつ きょうしつ（きゅうけい）",
    "ベッドで仮眠をとります。": "ベッドで ねます。",
    "HPを30%回復します。": "HPが 30% かいふくします。",
    "道具を改良します。": "どうぐを かいりょう します。",
    "カード1枚の性能を上げます。": "カード 1まいを つよくします。",
    "怪しい実験を行います。": "あやしい じっけんを します。",
    "2枚のカードを混ぜてキメラカードを作成します。": "2まいの カードを まぜて キメラカードを つくります。",
    "(50%の確率で鍵が開いています)": "(はんぶんの かくりつで カギが あいています)",
    "マップアイコン": "マップの マーク",
    "通常の敵（生徒・動物）": "ふつうの てき（せいと・どうぶつ）",
