    "ターン終了時にダメージ。数値が1減る。": "ターンの おわりに ダメージ. すうじが 1 へる。",
    "トゲトゲ (Thorns)": "トゲトゲ (はんげき)",
    "攻撃を受けると相手にダメージ。": "こうげきを うけると あいてに ダメージ。",
